3	#include <elapsedMillis.h>
4	
5	#define SERVOMIN 120
6	#define SERVOMAX 550
7	
8	Adafruit_PWMServoDriver pwm = Adafruit_PWMServoDriver();
9	
10	byte button = A0; // on/off button
11	bool lastButtonState;
12	bool currentButtonState;
13	bool on;
14	
15	int lightIn = A1; // light pin and value for light punishment
16	int lightValue;
17	
18	int jiggleCounter = 0;
19	
20	// mid,upR,upRB,upL,upLB,fwdR,fwdL,bwdR,bwdL
21	int movement[3][9] = {
22	  {90,110,70,70,110,125,60,65,120}, // straight
23	  {90,110,70,70,110,130,60,70,120}, // left
24	  {90,110,70,70,110,120,60,60,120}  // right
25	};
26	
27	int currentMovement = 0;
28	
29	struct VECTOR {
30	  int a, b;
31	};
32	
33	struct LEG {
34	  int sPin;
35	  int rPin;
36	  int switchPin;
37	  int touchPin;
38	  VECTOR pos;
39	  VECTOR target;
40	  bool switchState;
41	  bool touchState;
42	
43	  void move () {
44	    if (target.a != pos.a) {
45	      pos.a += ((target.a > pos.a) ? 1 : (-1));
46	      pwm.setPWM(sPin, 0, map(pos.a, 0, 180, SERVOMIN, SERVOMAX));
47	    }
48	    if (target.b != pos.b) {
49	      pos.b += ((target.b > pos.b) ? 1 : (-1));
50	      pwm.setPWM(rPin, 0, map(pos.b, 0, 180, SERVOMIN, SERVOMAX));
51	    }
52	  }
53	
54	  void setTarget (VECTOR t) {
55	    target = t;
56	  }
57	};
58	
59	LEG a, b, c, d, e, f;
60	
61	elapsedMillis t;
62	
63	int phase;
64	
65	void setup() {
66	  Serial.begin(9600);
67	
68	  pwm.begin();
69	  pwm.setPWMFreq(50);
70	
71	  stand();
72	  delay(1000); // WICHTIG ANSONSTEN BEWEGUNGEN NICHT ABGESCHLOSSEN
73	
74	  a = {0, 1, 2, 8, {90, 90}, {90, 90}};
75	  b = {2, 3, 3, 9, {90, 90}, {90, 90}};
76	  c = {4, 5, 4, 10, {90, 90}, {90, 90}};
77	  d = {6, 7, 5, 11, {90, 90}, {90, 90}};
78	  e = {8, 9, 6, 12, {90, 90}, {90, 90}};
79	  f = {10, 11, 7, 13, {90, 90}, {90, 90}};
80	
81	  pinMode(button, INPUT_PULLUP);
82	
83	  for (int i = 2; i < 14; i++) {
84	    pinMode(i, INPUT_PULLUP);
85	  }
86	}
87	
88	void loop() {
89	  a.move();
90	  b.move();
91	  c.move();
92	  d.move();
93	  e.move();
94	  f.move();
95	  delay(10); // ZEIT ZUM BEWEGEN DES SERVOS
96	
97	
98	  lastButtonState = currentButtonState;
99	  currentButtonState = digitalRead(button);
100	
101	  if (currentButtonState != lastButtonState && currentButtonState == LOW) {
102	    on = !on;
103	    currentMovement = random(0,3); // -> 0-2
104	  }
105	
106	  if (on == false) {
107	    stand();
108	
109	    for (int i = 8; i < 14; i++) {
110	      if (digitalRead(i) == HIGH) {
111	        Serial.println("TOUCH DETECTED");
112	        jiggleCounter = 100;
113	      }
114	    }
115	
116	    int lightValue = analogRead(lightIn);
117	    Serial.println(lightValue);
118	    if (lightValue <= 400) {
119	      jiggleCounter = 100;
120	    }
121	
122	    if (jiggleCounter > 0) {
123	      jiggleCounter--;
124	      jiggle();
125	    }
126	
127	    return;
128	  }
129	
130	
131	  if (t > 500) {
132	    t = 0;
133	
134	    if (phase == 0) {
135	      a.setTarget({movement[currentMovement][6], movement[currentMovement][3]});
136	      e.setTarget({movement[currentMovement][5], movement[currentMovement][1]});
137	
138	      b.setTarget({movement[currentMovement][8], movement[currentMovement][0]});
139	      f.setTarget({movement[currentMovement][7], movement[currentMovement][0]});
140	
141	      c.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
142	      d.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
143	
144	    }
145	    if (phase == 1) {
146	      a.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
147	      e.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
148	
149	      b.setTarget({movement[currentMovement][6], movement[currentMovement][3]});
150	      f.setTarget({movement[currentMovement][4], movement[currentMovement][2]});
151	
152	      c.setTarget({movement[currentMovement][8], movement[currentMovement][0]});
153	      d.setTarget({movement[currentMovement][7], movement[currentMovement][0]});
154	
155	
156	    }
157	    if (phase == 2) {
158	      a.setTarget({movement[currentMovement][8], movement[currentMovement][0]});
159	      e.setTarget({movement[currentMovement][7], movement[currentMovement][0]});
160	
161	      b.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
162	      f.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
163	
164	      c.setTarget({movement[currentMovement][6], movement[currentMovement][4]});
165	      d.setTarget({movement[currentMovement][5], movement[currentMovement][1]});
166	
167	    }
168	
169	    phase = (phase + 1) % 3;
170	
171	  }
172	
173	
174	}
175	
176	void stand() {
177	  a.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
178	  b.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
179	  c.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
180	  d.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
181	  e.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
182	  f.setTarget({movement[currentMovement][0], movement[currentMovement][0]});
183	}
184	
185	void jiggle() {
186	  a.setTarget({(int)random(80, 100), (int)random(80, 100)});
187	  b.setTarget({(int)random(80, 100), (int)random(80, 100)});
188	  c.setTarget({(int)random(80, 100), (int)random(80, 100)});
